import {
  existsSync,
  mkdirSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { LATEST_VERSION, openDatabase } from '../db/database';
import { PresentationRepo } from '../db/presentations';
import {
  applyPendingRestore,
  backupLibrary,
  checkBackup,
  LIBRARY_FILE,
  requestRestore,
  rollBackRestore,
} from './backup';

/* Placeholder names and generated bytes only. */

/** A data folder with a library holding one presentation of this name, and its media. */
function dataFolder(name: string) {
  const dir = mkdtempSync(join(tmpdir(), 'drashti-backup-'));
  const db = openDatabase(join(dir, LIBRARY_FILE));
  const repo = new PresentationRepo(db);
  repo.insert({
    libraryId: repo.ensureLibrary('Default'),
    name,
    groups: [{ name: 'G', slides: [{ elements: [] }] }],
  });
  mkdirSync(join(dir, 'Media', 'stills'), { recursive: true });
  writeFileSync(join(dir, 'Media', `${name}.txt`), name);
  writeFileSync(join(dir, 'Media', 'stills', 'still.bin'), Buffer.alloc(1000, 7));
  return { dir, db };
}

const names = (file: string) => {
  const db = openDatabase(file);
  const list = new PresentationRepo(db).list().map((p) => p.name);
  db.close();
  return list;
};

const options = (now: Date, mediaDir: string | null) => ({
  mediaDir,
  app: '1.0.0',
  schema: LATEST_VERSION,
  now,
});

describe('backing up the library', () => {
  it('copies the library and, when asked, the media into a new folder named in local time', async () => {
    const { dir, db } = dataFolder('Placeholder One');
    // Big enough to be streamed, so the progress moves while it copies.
    writeFileSync(join(dir, 'Media', 'video.bin'), Buffer.alloc(17 * 1024 * 1024, 1));
    const into = mkdtempSync(join(tmpdir(), 'drashti-backups-'));
    const now = new Date(2026, 8, 29, 18, 30);
    const progress: [number, number][] = [];
    const withMedia = await backupLibrary(db, into, {
      ...options(now, join(dir, 'Media')),
      onProgress: (done, total) => progress.push([done, total]),
    });
    expect(withMedia).toEqual({ folder: join(into, 'Drashti backup 2026-09-29 18-30'), mediaFiles: 3 });
    expect(names(join(withMedia.folder, LIBRARY_FILE))).toEqual(['Placeholder One']);
    expect(readdirSync(join(withMedia.folder, 'Media')).sort()).toEqual([
      'Placeholder One.txt',
      'stills',
      'video.bin',
    ]);
    expect(readFileSync(join(withMedia.folder, 'Media', 'stills', 'still.bin'))).toEqual(
      Buffer.alloc(1000, 7),
    );
    const total = 17 * 1024 * 1024 + 1000 + 'Placeholder One'.length;
    expect(progress.at(-1)).toEqual([total, total]);
    expect(progress.length).toBeGreaterThan(3);
    expect(JSON.parse(readFileSync(join(withMedia.folder, 'backup.json'), 'utf8'))).toMatchObject({
      app: '1.0.0',
      schema: LATEST_VERSION,
      media: true,
    });

    const only = await backupLibrary(db, into, options(now, null));
    expect(only).toEqual({ folder: join(into, 'Drashti backup 2026-09-29 18-30 (2)'), mediaFiles: 0 });
    expect(existsSync(join(only.folder, 'Media'))).toBe(false);
    expect(checkBackup(only.folder, LATEST_VERSION)).toMatchObject({
      ok: true,
      media: false,
      schema: LATEST_VERSION,
    });
    expect(checkBackup(withMedia.folder, LATEST_VERSION)).toMatchObject({ ok: true, media: true });
  });

  it('leaves nothing behind when a backup fails', async () => {
    const { dir, db } = dataFolder('Placeholder One');
    db.close();
    const into = mkdtempSync(join(tmpdir(), 'drashti-backups-'));
    await expect(backupLibrary(db, into, options(new Date(), join(dir, 'Media')))).rejects.toThrow();
    expect(readdirSync(into)).toEqual([]);
  });

  it('refuses folders that are not finished backups, and libraries from a newer Drashti', async () => {
    const { db } = dataFolder('Placeholder One');
    const into = mkdtempSync(join(tmpdir(), 'drashti-backups-'));
    const { folder } = await backupLibrary(db, into, options(new Date(), null));
    const refused = (at: string, schema = LATEST_VERSION) => {
      const check = checkBackup(at, schema);
      return check.ok ? null : check.code;
    };
    expect(refused(folder)).toBeNull();
    expect(refused(folder, LATEST_VERSION - 1)).toBe('newer');
    expect(refused(into)).toBe('no-library');
    rmSync(join(folder, 'backup.json'));
    expect(refused(folder)).toBe('unfinished');
  });
});

describe('restoring the library at the next start', () => {
  it('puts the backup in place and keeps the current library and media as a backup of their own', async () => {
    const backup = dataFolder('Placeholder From Backup');
    const saved = await backupLibrary(
      backup.db,
      mkdtempSync(join(tmpdir(), 'drashti-backups-')),
      options(new Date(), join(backup.dir, 'Media')),
    );
    const current = dataFolder('Placeholder Current');
    current.db.close();
    requestRestore(current.dir, saved.folder);
    const outcome = applyPendingRestore(current.dir, {
      schema: LATEST_VERSION,
      app: '1.0.0',
      now: new Date(2026, 8, 30, 8, 0),
    });
    expect(outcome).toEqual({
      restored: true,
      from: saved.folder.split(/[\\/]/u).at(-1),
      keptIn: 'Before restore 2026-09-30 08-00',
      media: true,
    });
    expect(names(join(current.dir, LIBRARY_FILE))).toEqual(['Placeholder From Backup']);
    expect(readdirSync(join(current.dir, 'Media')).sort()).toEqual(['Placeholder From Backup.txt', 'stills']);
    const kept = join(current.dir, 'Backups', 'Before restore 2026-09-30 08-00');
    expect(names(join(kept, LIBRARY_FILE))).toEqual(['Placeholder Current']);
    expect(readdirSync(join(kept, 'Media')).sort()).toEqual(['Placeholder Current.txt', 'stills']);
    // The library from before is itself a finished backup, so a restore can be undone the same way.
    expect(checkBackup(kept, LATEST_VERSION)).toMatchObject({ ok: true, media: true });
    expect(readdirSync(current.dir).filter((f) => f.includes('restor'))).toEqual([]);
    // Done once: the next start has nothing to do.
    expect(
      applyPendingRestore(current.dir, { schema: LATEST_VERSION, app: '1.0.0', now: new Date() }),
    ).toEqual({
      restored: false,
      code: null,
      message: null,
    });
  });

  it('keeps the current media folder when the backup has only the library', async () => {
    const backup = dataFolder('Placeholder From Backup');
    const saved = await backupLibrary(
      backup.db,
      mkdtempSync(join(tmpdir(), 'drashti-backups-')),
      options(new Date(), null),
    );
    const current = dataFolder('Placeholder Current');
    current.db.close();
    requestRestore(current.dir, saved.folder);
    expect(
      applyPendingRestore(current.dir, { schema: LATEST_VERSION, app: '1.0.0', now: new Date() }),
    ).toMatchObject({
      restored: true,
      media: false,
    });
    expect(names(join(current.dir, LIBRARY_FILE))).toEqual(['Placeholder From Backup']);
    expect(readdirSync(join(current.dir, 'Media')).sort()).toEqual(['Placeholder Current.txt', 'stills']);
  });

  it('leaves the library alone when the backup cannot be restored', () => {
    const current = dataFolder('Placeholder Current');
    current.db.close();
    requestRestore(current.dir, mkdtempSync(join(tmpdir(), 'drashti-not-a-backup-')));
    const outcome = applyPendingRestore(current.dir, {
      schema: LATEST_VERSION,
      app: '1.0.0',
      now: new Date(),
    });
    expect(outcome.restored ? null : outcome.code).toBe('no-library');
    expect(outcome.restored ? '' : outcome.message).toContain('not restored');
    expect(names(join(current.dir, LIBRARY_FILE))).toEqual(['Placeholder Current']);
    expect(existsSync(join(current.dir, 'Backups'))).toBe(false);
  });

  it('moves upgrade copies (drashti.sqlite.v<N>.bak) with the library they belong to', async () => {
    const backup = dataFolder('Placeholder From Backup');
    const saved = await backupLibrary(
      backup.db,
      mkdtempSync(join(tmpdir(), 'drashti-backups-')),
      options(new Date(), null),
    );
    const current = dataFolder('Placeholder Current');
    current.db.close();
    writeFileSync(join(current.dir, `${LIBRARY_FILE}.v3.bak`), 'old upgrade copy');
    requestRestore(current.dir, saved.folder);
    const outcome = applyPendingRestore(current.dir, {
      schema: LATEST_VERSION,
      app: '1.0.0',
      now: new Date(2026, 8, 30, 8, 0),
    });
    expect(outcome.restored).toBe(true);
    expect(readdirSync(current.dir).filter((f) => f.endsWith('.bak'))).toEqual([]);
    expect(
      readFileSync(
        join(current.dir, 'Backups', 'Before restore 2026-09-30 08-00', `${LIBRARY_FILE}.v3.bak`),
        'utf8',
      ),
    ).toBe('old upgrade copy');
  });
});

describe('putting the library back when a restored one will not open', () => {
  /** A restore of a backup, as at the start, before the restored library has been opened. */
  async function restoredOnce(withMedia: boolean) {
    const backup = dataFolder('Placeholder From Backup');
    const saved = await backupLibrary(
      backup.db,
      mkdtempSync(join(tmpdir(), 'drashti-backups-')),
      options(new Date(), withMedia ? join(backup.dir, 'Media') : null),
    );
    const current = dataFolder('Placeholder Current');
    current.db.close();
    writeFileSync(join(current.dir, `${LIBRARY_FILE}.v3.bak`), 'old upgrade copy');
    requestRestore(current.dir, saved.folder);
    const outcome = applyPendingRestore(current.dir, {
      schema: LATEST_VERSION,
      app: '1.0.0',
      now: new Date(2026, 8, 30, 8, 0),
    });
    if (!outcome.restored) throw new Error('not restored');
    // What a failed open of the restored library leaves: its journal, and an upgrade copy.
    writeFileSync(join(current.dir, `${LIBRARY_FILE}-wal`), 'restored journal');
    writeFileSync(join(current.dir, `${LIBRARY_FILE}.v8.bak`), 'restored upgrade copy');
    return { current, saved, keptIn: outcome.keptIn };
  }

  it('puts back the library and media from before, and keeps the restored copy apart', async () => {
    const { current, saved, keptIn } = await restoredOnce(true);
    const back = rollBackRestore(current.dir, keptIn, { now: new Date(2026, 8, 30, 8, 1) });
    expect(back).toEqual({ ok: true, failedIn: 'Failed restore 2026-09-30 08-01' });
    expect(names(join(current.dir, LIBRARY_FILE))).toEqual(['Placeholder Current']);
    expect(readdirSync(join(current.dir, 'Media')).sort()).toEqual(['Placeholder Current.txt', 'stills']);
    expect(readFileSync(join(current.dir, `${LIBRARY_FILE}.v3.bak`), 'utf8')).toBe('old upgrade copy');
    expect(existsSync(join(current.dir, `${LIBRARY_FILE}.v8.bak`))).toBe(false);
    const failed = join(current.dir, 'Backups', back.ok ? back.failedIn : '');
    expect(readdirSync(failed).sort()).toEqual([
      'Media',
      LIBRARY_FILE,
      `${LIBRARY_FILE}-wal`,
      `${LIBRARY_FILE}.v8.bak`,
    ]);
    expect(readdirSync(join(failed, 'Media')).sort()).toEqual(['Placeholder From Backup.txt', 'stills']);
    // The backup it came from is untouched, and the kept folder is still a finished backup.
    expect(checkBackup(saved.folder, LATEST_VERSION)).toMatchObject({ ok: true, media: true });
    expect(checkBackup(join(current.dir, 'Backups', keptIn), LATEST_VERSION)).toMatchObject({
      ok: true,
      media: false,
    });
  });

  it('leaves the media alone when the restore did not bring any', async () => {
    const { current, keptIn } = await restoredOnce(false);
    const back = rollBackRestore(current.dir, keptIn, { now: new Date(2026, 8, 30, 8, 1) });
    expect(back.ok).toBe(true);
    expect(names(join(current.dir, LIBRARY_FILE))).toEqual(['Placeholder Current']);
    expect(readdirSync(join(current.dir, 'Media')).sort()).toEqual(['Placeholder Current.txt', 'stills']);
  });

  it('says so when the library from before is not there', () => {
    const current = dataFolder('Placeholder Current');
    current.db.close();
    const back = rollBackRestore(current.dir, 'Before restore 2000-01-01 00-00', { now: new Date() });
    expect(back.ok ? '' : back.message).toContain('is not in Backups/Before restore 2000-01-01 00-00');
    expect(names(join(current.dir, LIBRARY_FILE))).toEqual(['Placeholder Current']);
  });
});
